/**
 * default-graph.js — DATA (not model, not view): the sample graph the
 * editor boots with when opened directly, before you load your own
 * graph.yaml via the file picker.
 *
 * Why base64 instead of a sibling .yaml file fetched at boot: this
 * project is meant to be double-clickable straight from the
 * filesystem (file://) as well as served locally, and a fetch() of a
 * sibling file is blocked by the browser under file://. Embedding the
 * bytes sidesteps that entirely, at the cost of this file being large
 * and not human-editable in place -- if you want to change the sample
 * graph, edit the source .yaml and re-run
 * scripts/embed-default-graph.py, don't hand-edit the base64 below.
 *
 * Regenerated from: kharcha_graph_storage.yaml
 */

const DEFAULT_GRAPH_B64 =
  "";

/**
 * atob() alone decodes to a raw binary string (one JS char per byte),
 * which mangles any multi-byte UTF-8 character (e.g. em-dashes) in
 * the source YAML into garbage. Convert the binary string to real
 * bytes first, then let TextDecoder interpret them as UTF-8.
 */
function decodeDefaultGraphYaml() {
  const binaryStr = atob(DEFAULT_GRAPH_B64);
  const bytes = new Uint8Array(binaryStr.length);
  for (let i = 0; i < binaryStr.length; i++) bytes[i] = binaryStr.charCodeAt(i);
  return new TextDecoder("utf-8").decode(bytes);
}

const GraphDefault = { decodeDefaultGraphYaml };

if (typeof window !== "undefined") {
  window.GraphDefault = GraphDefault;
}
